window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0e40ead05ec09869"]={"versions": [{"id": "FIG-0e40ead05ec09869", "releases": ["R19-11", "R20-11", "R21-11", "R22-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Gerendertes Dokumentations-Layout eines AUTOSAR-Anforderungselements (Instanz des Metamodell-Elements <code>StructuredReq</code> gemäß AUTOSAR <em>Generic Structure Template</em> / MSR-Dokumentationsmodell).\n</li><li><strong>Technischer Zweck:</strong> Formale, maschinenlesbare und tabellarisch standardisierte Repräsentation eines Spezifikationsitems (<code>SpecItem</code>) zur normativen Anforderungsdefinition (hier: Systemanforderung <code>RS_SYST_00020</code>). Es dient der konsistenten Dokumentengenerierung und der durchgängigen bidirektionalen Traceability (gemäß ASPICE und ISO 26262) innerhalb der AUTOSAR-Entwicklungsmethodik.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist die Strukturierung des Metamodell-Elements <code>StructuredReq</code> (Spezialisierung von <code>TraceableText</code> / <code>Identifiable</code>):</p>\n<ul class=\"fig-list\"><li><strong>Header / Identifikator:</strong>\n<ul class=\"fig-list\"><li><code>[RS_SYST_00020]</code>: Eindeutiger ShortName / Anforderungs-Identifier.\n</li><li><code>Title</code>: <em>Exclusion of signals from a specific physical line</em>.\n</li><li><code>Delimiters</code>: Formale Klammerung über das Anker-Zeichen <code>⌈</code> (Beginn des normativen Geltungsbereichs) und <code>⌋</code> (Ende).\n</li></ul>\n</li><li><strong>Attribut-Tabelle (<code>StructuredReq</code>-Properties):</strong>\n<ul class=\"fig-list\"><li><code>Type</code>: <code>valid</code> (Status/Gültigkeit des Requirements im Lebenszyklus).\n</li><li><code>Description</code>: Normative Kernanforderung – Fähigkeit der <em>System Constraint Description</em>, Signale vom Mapping auf spezifische physikalische Leitungen auszuschließen.\n</li><li><code>Rationale</code>: Begründung – Ungeeignetheit bestimmter physikalischer Kanäle (Geschwindigkeit, mangelnde Protokollsicherheit).\n</li><li><code>Dependencies</code>: Abhängigkeiten zu anderen Spezifikationsmodulen (<code>None identified</code>).\n</li><li><code>Use Case</code>: Anwendungsfall – Verhinderung des Mappings von Powertrain-Signalen auf Low-Speed-CAN-Busse aufgrund deterministischer Timing-Restriktionen.\n</li><li><code>Supporting Material</code>: Ergänzende externe Dokumente oder Artefakte (<code>–</code>).\n</li></ul>\n</li><li><strong>Traceability / Relationen:</strong>\n<ul class=\"fig-list\"><li>Upstream-Traceability-Referenzen: Verknüpfung zu übergeordneten Hauptanforderungen <code>(RS_Main_00150, RS_Main_00030)</code> am Fuß der Definition.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\"><li><strong>Laufzeit-Verhalten:</strong> Nicht zutreffend (statisches Spezifikations-/Metamodell-Artefakt ohne Target-Ausführung).\n</li><li><strong>Toolchain- / Generierungsablauf (Entwurfszeit):</strong>\n<ol class=\"fig-list\"><li><em>ARXML-Erfassung:</em> Modellierung der <code>StructuredReq</code> im MSR-Dokumentationsmodell inklusive Metadaten und Upstream-Ref-Tags.\n</li><li><em>Konsistenzprüfung:</em> Automatisierte Validierung der Traceability-Links (<code>RS_Main_00150</code>, <code>RS_Main_00030</code>) und Schema-Integrität.\n</li><li><em>DocGen-Kompilierung:</em> Rendering des XML-Fragments in standardisiertes PDF-Layout unter Beibehaltung der Begrenzer <code>⌈</code> und <code>⌋</code> für automatisierte Parser.\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>System Constraint Description (ARXML-Ebene):</strong>\n<ul class=\"fig-list\"><li><code>RS_SYST_00020</code> fordert im <em>System Template</em> Mechanismen (z. B. via <code>SignalPathConstraints</code> oder Mapping-Restriktionen), die verbieten, dass definierte <code>SystemSignal</code>-Instanzen auf bestimmte <code>CommunicationCluster</code> / <code>PhysicalChannel</code>-Instanzen geroutet werden.\n</li></ul>\n</li><li><strong>Konsequenz für System- und Stack-Entwickler:</strong>\n<ul class=\"fig-list\"><li>System-Design-Tools müssen unzulässige Signal-to-PDU- bzw. PDU-to-Channel-Mappings bei der Generierung der <em>System Configuration</em> (<code>EcuExtract</code>) abfangen und als Validierungsfehler melden.\n</li><li>Verhindert Fehlkonfigurationen im Kommunikations-Stack (z. B. Allokation von Signalen mit harter Echtzeit- oder Sicherheitsanforderung auf Low-Speed-Busse ohne deterministische Latenz).\n</li></ul>\n</li><li><strong>Traceability-Handhabung:</strong>\n<ul class=\"fig-list\"><li>Entwickler und Tool-Integratoren nutzen die eindeutigen Klammern <code>[RS_... ⌈ ... ⌋(...)</code>, um Spezifikationstexte verlustfrei in Requirements-Management-Tools (z. B. IBM DOORS, PTC Integrity) zu synchronisieren und Testabdeckungen bis auf BSW-Ebene nachzuweisen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c2f76b42d9c447bc", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Gerendertes Dokumentations-Layout eines AUTOSAR-Anforderungselements (Instanz des Metamodell-Elements <code>StructuredReq</code> gemäß AUTOSAR <em>Generic Structure Template</em> / MSR-Dokumentationsmodell).\n</li><li><strong>Technischer Zweck:</strong> Formale, maschinenlesbare und tabellarisch standardisierte Repräsentation eines Spezifikationsitems (<code>SpecItem</code>) zur normativen Anforderungsdefinition (hier: Software Requirement <code>SRS_Com_02040</code>). Es dient der konsistenten Dokumentengenerierung und der Modellierung von Modulanforderungen innerhalb der AUTOSAR-Entwicklungsmethodik.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist die Strukturierung des Metamodell-Elements <code>StructuredReq</code> (Spezialisierung von <code>TraceableText</code> / <code>Identifiable</code>):</p>\n<ul class=\"fig-list\"><li><strong>Header / Identifikator:</strong>\n<ul class=\"fig-list\"><li><code>[SRS_Com_02040]</code>: Eindeutiger ShortName / Anforderungs-Identifier.\n</li><li><code>Title</code>: <em>AUTOSAR COM and LargeDataCOM shall be configured by using XML as configuration language</em>.\n</li><li><code>Delimiters</code>: Formale Klammerung über das Anker-Zeichen <code>⌈</code> (Beginn des normativen Geltungsbereichs) und <code>⌋</code> (Ende).\n</li></ul>\n</li><li><strong>Attribut-Tabelle (<code>StructuredReq</code>-Properties):</strong>\n<ul class=\"fig-list\"><li><code>Description</code>: Normative Kernanforderung – Konfiguration von AUTOSAR COM und LargeDataCOM mittels XML gemäß ECU Configuration Template; Definition der Konfigurationsparameter obliegt den Referenzen <code>[3]</code> und <code>[4]</code>.\n</li><li><code>Rationale</code>: Begründung – Etablierung einer einheitlichen Konfigurationssprache innerhalb von AUTOSAR.\n</li><li><code>Use Case</code>: Anwendungsfall – Konfiguration von AUTOSAR COM und LargeDataCOM.\n</li><li><code>Dependencies</code>: Abhängigkeiten (<code>–</code>).\n</li><li><code>Supporting Material</code>: Ergänzende externe Dokumente oder Spezifikationsreferenzen (<code>[9]</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Laufzeit-Verhalten:</strong> Nicht zutreffend (statisches Spezifikations-/Metamodell-Artefakt ohne Target-Ausführung).\n</li><li><strong>Toolchain- / Generierungsablauf (Entwurfszeit):</strong>\n<ol class=\"fig-list\"><li><em>ARXML-Erfassung:</em> Modellierung der <code>StructuredReq</code> im MSR-Dokumentationsmodell inklusive Metadaten und Upstream-Ref-Tags.\n</li><li><em>Konsistenzprüfung:</em> Automatisierte Validierung der Traceability-Links (<code>RS_Main_00150</code>, <code>RS_Main_00030</code>) und Schema-Integrität.\n</li><li><em>DocGen-Kompilierung:</em> Rendering des XML-Fragments in standardisiertes PDF-Layout unter Beibehaltung der Begrenzer <code>⌈</code> und <code>⌋</code> für automatisierte Parser.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ECU Configuration Template &amp; BSW-Konfiguration (ARXML-Ebene):</strong>\n<ul class=\"fig-list\"><li><code>SRS_Com_02040</code> definiert die methodische Vorgabe, dass die Parametrierung der Kommunikationsmodule (<code>Com</code>, <code>LargeDataCom</code>) auf standardisiertem XML/ARXML basieren muss.\n</li></ul>\n</li><li><strong>Konsequenz für BSW- und Tool-Entwickler:</strong>\n<ul class=\"fig-list\"><li>BSW-Konfiguratoren und Generatoren müssen Parameterstrukturen gemäß ECU Configuration Parameter Definition (<code>EcucParamConfContainerDef</code>) einlesen und verarbeiten.\n</li><li>Sicherstellung der Interoperabilität von BSW-Stacks über standardisierte XML-basierte Konfigurationsbeschreibungen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-0e40ead05ec09869", "to": "FIG-c2f76b42d9c447bc", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Ausgetauschtes Beispiel-SpecItem: Anstelle von <code>[RS_SYST_00020]</code> (&quot;Exclusion of signals from a specific physical line&quot;) wird nun <code>[SRS_Com_02040]</code> (&quot;AUTOSAR COM and LargeDataCOM shall be configured by using XML as configuration language&quot;) als exemplarische Repräsentation von <code>StructuredReq</code> dargestellt.\n</li><li>Tabellenzeilen: Attribut <code>Type</code> (<code>valid</code>) entfällt im Beispiel; Reihenfolge der verbleibenden Attribute geändert zu <code>Description</code>, <code>Rationale</code>, <code>Use Case</code>, <code>Dependencies</code> (<code>–</code> statt <code>None identified</code>) und <code>Supporting Material</code> (<code>[9]</code> statt <code>–</code>).\n</li><li>Traceability-Referenzen: Upstream-Referenzen <code>(RS_Main_00150, RS_Main_00030)</code> am Fuß der Definition entfallen im Beispiel.\n</li></ul>"}]};
